head.script:

    		//_SITE_SystemLang = "ENG";
    		_SITE_CreateObject = false;

		    //Veraport 다운로드 URL 설정
		    function fn_download_Veraport(pkgType) {
		        document.location = fn_getVpDownloadURL(pkgType, true);
		    }

		    function fn_download_noitce(objectName, pkgType, downURL) {
		        var notice = "설치 후에는 반드시 새로고침을 하거나 다시 접속해주세요.";
		        if (instConfig.isDebug) notice += "\n\n설치파일다운로드정보[" + objectName + "]["+VP_platformInfo.type+","+VP_platformInfo.name+"]["+pkgType+"]\n" + downURL;

//		        alert(notice);
		        if (downURL != "") document.location = downURL;
		    }

		    //DelfinoG3 다운로드 URL 설정
		    function fn_download_DelfinoG3(pkgType) {
		        var _baseURL = document.location.protocol+"//"+document.location.host+"/pluginfree/wizvera/delfino/down";
		        var downURL = _baseURL + "/delfino-g3.exe";
//		        var _baseURL = "http://help.wizvera.com/svc/wizvera/delfino";
//		        if (VP_platformInfo.x64) downURL = _baseURL + "/delfino-g3.exe";

		        fn_download_noitce("DelfinoG3", pkgType, downURL);
		    }

		    //NOS 다운로드 URL 설정
		    function fn_download_NOS(pkgType) {
//		    	var _baseURL = document.location.protocol+"//"+document.location.host+"/pluginfree/nos/down";
				var _baseURL ="";
				if(_mode == "REAL") {
		    		//_baseURL = "https://supdate.nprotect.net/nprotect/nos_service/windows/install/kbsavings";
		    		  _baseURL =   "https://supdate.nprotect.net/nprotect/nos_service/windows/install";
		    	} else {
		    		_baseURL = document.location.protocol+"//"+document.location.host+"/pluginfree/nos/down";
		    	}
		        var downURL = _baseURL + "/nos_setup.exe";
		        if (VP_platformInfo.x64) downURL = _baseURL + "/nos_setup.exe";

		        fn_download_noitce("NOS", pkgType, downURL);
		    }

		    //IPinsideLWS 다운로드 URL 설정
		    function fn_download_IPinsideLWS(pkgType) {
		    	var _baseURL = document.location.protocol+"//"+document.location.host+"/pluginfree/interezen";
		        var downURL = _baseURL + "/IPinsideLWS.exe";
		        if (VP_platformInfo.x64) downURL = _baseURL + "/IPinsideLWS.exe";

		        fn_download_noitce("IPinsideLWS", pkgType, downURL);
		    }

		    //SavingBankKTB 다운로드 URL 설정
		    function fn_download_SavingBankKTB(pkgType) {
		    	var _baseURL = document.location.protocol+"//"+document.location.host+"/pluginfree/ktbRealIp";
		        var downURL = _baseURL + "/SavingBankKTBSecLoggerInst.exe";
		        if (VP_platformInfo.x64) downURL = _baseURL + "/SavingBankKTBSecLoggerInst.exe";

		        fn_download_noitce("SavingBankKTB", pkgType, downURL);
		    }

			//nKISSCAP 다운로드 URL 설정
		    function fn_download_nKISSCAP(pkgType) {
		    	var _baseURL = document.location.protocol+"//"+document.location.host+"/pluginfree/scraping";
		        var downURL = _baseURL + "/KISSCAP.exe";
		        if (VP_platformInfo.x64) downURL = _baseURL + "/KISSCAP.exe";

		        fn_download_noitce("nKISSCAP", pkgType, downURL);
		    }

    		// 전체설치
			scwin.VP_btn_install_onclick = function(e) {
				preventDefaultEvent(e);
				SITE_axInstallVP(instConfig.objectDefType, false);
			};

			// 통합설치툴 설치
			scwin.object_download_Veraport_onclick = function(e) {
				preventDefaultEvent(e);
				fn_download_Veraport("");
			};

			// 델피노 설치
			scwin.object_download_DelfinoG3_onclick = function(e) {
				preventDefaultEvent(e);
				var veraportStatus = VP_getObjectStatus(instCode.VERAPORT);
	    		if (veraportStatus != instCode.STATUS_INST_OK) {
					fn_download_DelfinoG3("DelfinoG3");
				} else {
					SITE_axInstallVP("DelfinoG3");
				}
			};

    		// 키보드 보안 설치
			scwin.object_download_NOS_onclick = function(e) {
				preventDefaultEvent(e);
				var veraportStatus = VP_getObjectStatus(instCode.VERAPORT);
	    		if (veraportStatus != instCode.STATUS_INST_OK) {
					fn_download_NOS("NOS");
				} else {
					SITE_axInstallVP("NOS");
				}
			};

			// IPinsideLWS 설치
			scwin.object_download_IPinsideLWS_onclick = function(e) {
				preventDefaultEvent(e);
				var veraportStatus = VP_getObjectStatus(instCode.VERAPORT);
	    		if (veraportStatus != instCode.STATUS_INST_OK) {
					fn_download_IPinsideLWS("IPinsideLWS");
				} else {
					SITE_axInstallVP("IPinsideLWS");
				}
			};

			// SavingBankKTB 설치
			scwin.object_download_SavingBankKTB_onclick = function(e) {
				preventDefaultEvent(e);
				var veraportStatus = VP_getObjectStatus(instCode.VERAPORT);
	    		if (veraportStatus != instCode.STATUS_INST_OK) {
					fn_download_SavingBankKTB("SavingBankKTB");
				} else {
					SITE_axInstallVP("SavingBankKTB");
				}
			};

			// nKISSCAP 설치
			scwin.object_download_nKISSCAP_onclick = function(e) {
				preventDefaultEvent(e);
				var veraportStatus = VP_getObjectStatus(instCode.VERAPORT);
	    		if (veraportStatus != instCode.STATUS_INST_OK) {
					fn_download_nKISSCAP("nKISSCAP");
	    		} else {
					SITE_axInstallVP("nKISSCAP");
	    		}
			};

			timer_vpObjectLoad();                  //[필수]베라포트: ActiveX/Plugin 설치 확인 및 모듈 로딩
//			timer_vpMsgUpdate();                   //[필수]베라포트: 설치여부별 /안내메시지 변경 함수
			timer_vpBtnUpdate();                   //[필수]베라포트: 설치여부별 /전체설치,다운로드 버튼 변경 함수
			timer_objectUpdate(instCode.VERAPORT); //베라포트: 설치여부별 /상태,다운로드 버튼 변경 함수
			timer_objectUpdate("DelfinoG3");       //공인인증: 설치여부별 /상태,다운로드 버튼 변경 함수
			timer_objectUpdate("NOS");             //키보드보안: 설치여부별 /상태,다운로드 버튼 변경 함수
			timer_objectUpdate("IPinsideLWS");   //SavingBankKTB: 설치여부별 /상태,다운로드 버튼 변경 함수
			//timer_objectUpdate("SavingBankKTB");   //SavingBankKTB: 설치여부별 /상태,다운로드 버튼 변경 함수
			timer_objectUpdate("nKISSCAP");        //nKISSCAP: 설치여부별 /상태,다운로드 버튼 변경 함수

			var parameterUrl = fn_getUrlParameter("url");
//			if(parameterUrl.indexOf("/jsp/ibankMng/") != -1) { // 인터넷뱅킹이면 IP수집기 설치 오픈
//				savingBankKtbCheckTr.show("");
//				timer_objectUpdate("SavingBankKTB");   //SavingBankKTB: 설치여부별 /상태,다운로드 버튼 변경 함수
//			} 

			SITE_vpObjectInstall();//[필수]베라포트: 자동설치 및 차단감지
			if (VP_config.useHandler) execVP_isInstall(timer_vpHandlerLoad);//[필수]베라포트: non-Plugin 설치 확인/START

			// 20160826 김창석 - 사잇돌2대출 추가  
         	if(parameterUrl.indexOf("/jsp/kindLoanMng/loanLimit/loanLimit_01") != -1 || parameterUrl.indexOf("/loanService/onlineService.xml") != -1 || 
         		// 20171114 박종민 - 추가대출, 간편한도조회, 직장인빠른대출 추가
         		/*
         		parameterUrl.indexOf("/jsp/kindLoanMng/addApplyOneStop/addApplyOneStop_01.xml") != -1 || parameterUrl.indexOf("/jsp/kindLoanMng/easyLimit/easyLimit_01.xml") != -1 || parameterUrl.indexOf("/jsp/kindLoanMng/oneStop/oneStop_02.xml") != -1 || 
         		parameterUrl.indexOf("/jsp/kindLoanMng/loanApply/kindLoanAdd_01.xml") != -1 || parameterUrl.indexOf("/jsp/sgiLoanMng/loanLimit/sgiloanLimit_01") != -1) { // 착한대출 통합한도조회, 마이페이지, 온라인 서류제출서비스
         		*/
         		/* 20171201 모바일웹 관련 수정 - 김창석 START */
         		parameterUrl.indexOf("/addApplyOneStop/addApplyOneStop_01.xml") != -1 || parameterUrl.indexOf("/easyLimit/easyLimit_01.xml") != -1 || parameterUrl.indexOf("/oneStop/oneStop_02.xml") != -1 || 
         		parameterUrl.indexOf("/jsp/kindLoanMng/loanApply/kindLoanAdd_01.xml") != -1 || parameterUrl.indexOf("/jsp/sgiLoanMng/loanLimit/sgiloanLimit_01") != -1 ||
         		parameterUrl.indexOf("/jsp/kindLoanMng/myLoanPage/kindMyPageRateLower_01.xml") != -1 ||
         		parameterUrl.indexOf("/jsp/stockLoanMng/loanApply/regCreditInfoAgree.xml") != -1 || parameterUrl.indexOf("/jsp/stockLoanMng/loanDWST/chgAmtSelect.xml") != -1 ||
         		parameterUrl.indexOf("/myLoanPage/onlineService.xml") != -1 || parameterUrl.indexOf("/jsp/loanItemInfo/loanGuide/rateLowerDemand.xml") != -1 || parameterUrl.indexOf("/jsp/loanItemInfo/loanGuide/rateLowerAcctNoList.xml") != -1 ) { // 착한대출 통합한도조회, 마이페이지, 온라인 서류제출서비스, 스탁론 추가 20190923
				/* 20171201 모바일웹 관련 수정 - 김창석 END */
				scrappingCheckTr.show("");
         	} else if(parameterUrl.indexOf("/jsp/stockLoanMng/") != -1 || parameterUrl.indexOf("/jsp/sunshineLoanMng/") != -1 || 
         		parameterUrl.indexOf("/jsp/loanItemInfo/") != -1 || parameterUrl.indexOf("/jsp/consumerCenter/") != -1 ||
         		parameterUrl.indexOf("/jsp/kindLoanMng/") != -1 || parameterUrl.indexOf("/jsp/sgiLoanMng/") != -1) { // 스탁론, 햇살론, 착한대출, 대출상품, 고객센터

         	} else {
         		//savingBankKtbCheckTr.show("");
         		IPinsideLWSTr.show("");
         	}
